CREATE TABLE IF NOT EXISTS fantasy_auction_rounds(league_id TEXT NOT NULL,listing_id TEXT NOT NULL,day INTEGER NOT NULL,min_cents INTEGER NOT NULL,closes_at INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'open',winner_uid TEXT,winning_cents INTEGER,lease_until INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(league_id,listing_id,day));
CREATE INDEX IF NOT EXISTS fantasy_auction_due ON fantasy_auction_rounds(status,closes_at);
CREATE TABLE IF NOT EXISTS fantasy_auction_bids(league_id TEXT NOT NULL,listing_id TEXT NOT NULL,day INTEGER NOT NULL,uid TEXT NOT NULL,amount_cents INTEGER NOT NULL CHECK(amount_cents>0),first_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,gross_cents INTEGER NOT NULL,week INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'active',PRIMARY KEY(league_id,listing_id,day,uid),FOREIGN KEY(league_id,uid) REFERENCES fantasy_members(league_id,uid));
CREATE INDEX IF NOT EXISTS fantasy_auction_user ON fantasy_auction_bids(league_id,uid);
CREATE TABLE IF NOT EXISTS fantasy_auction_wins(trade_id TEXT PRIMARY KEY,league_id TEXT NOT NULL,listing_id TEXT NOT NULL,day INTEGER NOT NULL,uid TEXT NOT NULL,amount_cents INTEGER NOT NULL);
CREATE TRIGGER IF NOT EXISTS fantasy_bid_guard_insert BEFORE INSERT ON fantasy_auction_bids BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM fantasy_auction_rounds r WHERE r.league_id=NEW.league_id AND r.listing_id=NEW.listing_id AND r.day=NEW.day AND r.status='open' AND r.lease_until=0 AND r.closes_at>NEW.updated_at AND NEW.amount_cents>=r.min_cents) THEN RAISE(ABORT,'FANTASY_BID_CLOSED') END;
 SELECT CASE WHEN NEW.gross_cents+COALESCE((SELECT delta_cents FROM fantasy_wallet_cents WHERE league_id=NEW.league_id AND uid=NEW.uid),-99999999)-COALESCE((SELECT SUM(b.amount_cents) FROM fantasy_auction_bids b JOIN fantasy_auction_rounds r ON r.league_id=b.league_id AND r.listing_id=b.listing_id AND r.day=b.day WHERE b.league_id=NEW.league_id AND b.uid=NEW.uid AND r.status='open' AND b.status='active' AND (b.listing_id!=NEW.listing_id OR b.day!=NEW.day)),0)<NEW.amount_cents THEN RAISE(ABORT,'FANTASY_BID_FUNDS') END;
 SELECT CASE WHEN (SELECT COUNT(*) FROM fantasy_roster WHERE league_id=NEW.league_id AND uid=NEW.uid)+(SELECT COUNT(*) FROM fantasy_auction_bids b JOIN fantasy_auction_rounds r ON r.league_id=b.league_id AND r.listing_id=b.listing_id AND r.day=b.day WHERE b.league_id=NEW.league_id AND b.uid=NEW.uid AND r.status='open' AND b.status='active' AND (b.listing_id!=NEW.listing_id OR b.day!=NEW.day))>=16 THEN RAISE(ABORT,'FANTASY_ROSTER_MAX') END;
 SELECT CASE WHEN (SELECT COUNT(*) FROM fantasy_trades WHERE league_id=NEW.league_id AND buyer_uid=NEW.uid AND week_key=NEW.week)+(SELECT COUNT(*) FROM fantasy_auction_bids b JOIN fantasy_auction_rounds r ON r.league_id=b.league_id AND r.listing_id=b.listing_id AND r.day=b.day WHERE b.league_id=NEW.league_id AND b.uid=NEW.uid AND b.week=NEW.week AND r.status='open' AND b.status='active' AND b.status='active' AND (b.listing_id!=NEW.listing_id OR b.day!=NEW.day))>=CAST(json_extract((SELECT settings_json FROM fantasy_leagues WHERE id=NEW.league_id),'$.transfers') AS INTEGER) THEN RAISE(ABORT,'FANTASY_TRANSFERS') END;
END;
CREATE TRIGGER IF NOT EXISTS fantasy_bid_guard_update BEFORE UPDATE ON fantasy_auction_bids WHEN NEW.status='active' BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM fantasy_auction_rounds r WHERE r.league_id=NEW.league_id AND r.listing_id=NEW.listing_id AND r.day=NEW.day AND r.status='open' AND r.lease_until=0 AND r.closes_at>NEW.updated_at AND NEW.amount_cents>=r.min_cents) THEN RAISE(ABORT,'FANTASY_BID_CLOSED') END;
 SELECT CASE WHEN NEW.gross_cents+COALESCE((SELECT delta_cents FROM fantasy_wallet_cents WHERE league_id=NEW.league_id AND uid=NEW.uid),-99999999)-COALESCE((SELECT SUM(b.amount_cents) FROM fantasy_auction_bids b JOIN fantasy_auction_rounds r ON r.league_id=b.league_id AND r.listing_id=b.listing_id AND r.day=b.day WHERE b.league_id=NEW.league_id AND b.uid=NEW.uid AND r.status='open' AND b.status='active' AND (b.listing_id!=NEW.listing_id OR b.day!=NEW.day)),0)<NEW.amount_cents THEN RAISE(ABORT,'FANTASY_BID_FUNDS') END;
END;

DROP TRIGGER IF EXISTS fantasy_trade_guard;
CREATE TRIGGER fantasy_trade_guard BEFORE INSERT ON fantasy_trades BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM fantasy_roster WHERE league_id=NEW.league_id AND player_id=NEW.player_id AND (NEW.offer_id IS NULL OR uid=NEW.buyer_uid)) THEN RAISE(ABORT,'FANTASY_OWNED') END;
 SELECT CASE WHEN COALESCE((SELECT delta_cents FROM fantasy_wallet_cents WHERE league_id=NEW.league_id AND uid=NEW.buyer_uid),-999999999)+ROUND(NEW.budget_units*50)-COALESCE((SELECT SUM(b.amount_cents) FROM fantasy_auction_bids b JOIN fantasy_auction_rounds r ON r.league_id=b.league_id AND r.listing_id=b.listing_id AND r.day=b.day WHERE b.league_id=NEW.league_id AND b.uid=NEW.buyer_uid AND r.status='open' AND b.status='active'),0)<ROUND(NEW.amount_units*50) THEN RAISE(ABORT,'FANTASY_FUNDS') END;
 SELECT CASE WHEN (SELECT COUNT(*) FROM fantasy_trades WHERE league_id=NEW.league_id AND buyer_uid=NEW.buyer_uid AND week_key=NEW.week_key)+(SELECT COUNT(*) FROM fantasy_auction_bids b JOIN fantasy_auction_rounds r ON r.league_id=b.league_id AND r.listing_id=b.listing_id AND r.day=b.day WHERE b.league_id=NEW.league_id AND b.uid=NEW.buyer_uid AND b.week=NEW.week_key AND r.status='open' AND b.status='active')>=CAST(json_extract((SELECT settings_json FROM fantasy_leagues WHERE id=NEW.league_id),'$.transfers') AS INTEGER) THEN RAISE(ABORT,'FANTASY_TRANSFERS') END;
 SELECT CASE WHEN (SELECT COUNT(*) FROM fantasy_roster WHERE league_id=NEW.league_id AND uid=NEW.buyer_uid)+(SELECT COUNT(*) FROM fantasy_auction_bids b JOIN fantasy_auction_rounds r ON r.league_id=b.league_id AND r.listing_id=b.listing_id AND r.day=b.day WHERE b.league_id=NEW.league_id AND b.uid=NEW.buyer_uid AND r.status='open' AND b.status='active')>=16 THEN RAISE(ABORT,'FANTASY_ROSTER_MAX') END;
 SELECT CASE WHEN NEW.offer_id IS NULL AND NOT EXISTS(SELECT 1 FROM fantasy_auction_wins w WHERE w.trade_id=NEW.id AND w.league_id=NEW.league_id AND w.listing_id=NEW.listing_id AND w.uid=NEW.buyer_uid AND w.amount_cents=ROUND(NEW.amount_units*50)) THEN RAISE(ABORT,'FANTASY_AUCTION_REQUIRED') END;
 SELECT CASE WHEN NEW.offer_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM fantasy_offers o JOIN fantasy_roster r ON r.id=o.ownership_id WHERE o.id=NEW.offer_id AND o.league_id=NEW.league_id AND o.buyer_uid=NEW.buyer_uid AND o.seller_uid=NEW.seller_uid AND o.ownership_id=NEW.ownership_id AND o.player_id=NEW.player_id AND o.amount_units=NEW.amount_units AND o.status='pending' AND o.expires_at>NEW.created_at AND r.league_id=NEW.league_id AND r.uid=NEW.seller_uid AND r.player_id=NEW.player_id) THEN RAISE(ABORT,'FANTASY_OFFER_CHANGED') END;
END;
CREATE TRIGGER IF NOT EXISTS fantasy_gift_respects_market BEFORE INSERT ON fantasy_roster WHEN NEW.price_units=0 BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM fantasy_market_listings l WHERE l.league_id=NEW.league_id AND l.player_id=NEW.player_id AND l.retired_day IS NULL) THEN RAISE(ABORT,'FANTASY_GIFT_CHANGED') END;
END;
CREATE TRIGGER IF NOT EXISTS fantasy_auction_proof BEFORE INSERT ON fantasy_auction_wins BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM fantasy_auction_bids b JOIN fantasy_auction_rounds r ON r.league_id=b.league_id AND r.listing_id=b.listing_id AND r.day=b.day WHERE b.league_id=NEW.league_id AND b.listing_id=NEW.listing_id AND b.day=NEW.day AND b.uid=NEW.uid AND b.amount_cents=NEW.amount_cents AND b.status='active' AND r.status='closed' AND r.winner_uid=NEW.uid) THEN RAISE(ABORT,'FANTASY_BID_CHANGED') END;
END;
